  getWritable() {
    if ($isEphemeral(this)) {
      return this;
    }
    errorOnReadOnly();
    const editorState = getActiveEditorState();
    const editor = getActiveEditor();
    const key = this.__key;
    const cloneNotNeeded = editor._cloneNotNeeded;
    // Cast: a key always identifies the same node class.
    const writableNode = cloneNotNeeded.get(key);
    const selection = editorState._selection;
    if (selection !== null) {
      selection.setCachedNodes(null);
    }
    if (writableNode !== undefined) {
      // Transforms clear the dirty node set on each iteration to keep track on newly dirty nodes
      internalMarkNodeAsDirty(writableNode);
      return writableNode;
    }
    const nodeMap = editorState._nodeMap;
    // Cast: the nodeMap entry for this key is always the same node class.
    const latestNode = nodeMap.get(key);
    if (!(latestNode !== undefined)) {
      formatDevErrorMessage(`Lexical node does not exist in active editor state. Avoid using the same node references between nested closures from editorState.read/editor.update.`);
    }
    const mutableNode = $cloneWithProperties(latestNode);
    cloneNotNeeded.set(key, mutableNode);
    nodeMap.set(key, mutableNode);
    internalMarkNodeAsDirty(mutableNode);
    return mutableNode;
  }

